    "question": "¿Cómo aprendemos a pertenecer sin desaparecer, y qué perdemos y qué conservamos en ese proceso?",
    "decision_relevance": "Delimita el alcance investigativo."
  },
  "intended_use": {
    "uses": [
      "Investigar y desarrollar una tesis provisional para un videoensayo sobre identidad, pertenencia y adaptación, utilizando obras narrativas como materiales de análisis sin convertirlas en prueba científica ni decidir todavía la estructura narrativa final."
    ],
    "required_outputs": [
      "evidence_report"
    ]
  },
  "scope": {
    "included": [
      "Examinar cómo las personas construyen pertenencia en relaciones, grupos y estructuras sociales; qué prácticas de adaptación, reconocimiento y renuncia intervienen; bajo qué condiciones la pertenencia fortalece o erosiona la identidad; y cuáles son los límites para generalizar desde las obras y la evidencia disponible. No incluye diagnóstico clínico, coaching, resumen de obras, propaganda ni afirmaciones universales no sustentadas."
    ],
    "excluded": [
      "Producción editorial final"
    ]
  },
